for i in range(4):
    for j in range(4):
        print(f"\n=== Block [{i},{j}] ===")
        print(blocks[i][j])

# Let me count the most common colors in each block
for i in range(4):
    row_str = ""
    for j in range(4):
        block = blocks[i][j]
        counts = {}
        for c in block.flatten():
            counts[c] = counts.get(c, 0) + 1
        sorted_counts = sorted(counts.items(), key=lambda x: -x[1])
        top3 = sorted_counts[:3]
        row_str += f"{top3} "
    print(f"Row {i}: {row_str}")

# Full count of each color in the grid
